+        check("u", &u);
+
+        // A staircase: one X wall per Y band, the levels-only plane set's
+        // failure shape.
+        let step = region(
+            "step",
+            vec![vec![
+                (0.0, 0.0),
+                (10.0, 0.0),
+                (10.0, 3.0),
+                (7.0, 3.0),
+                (7.0, 6.0),
+                (4.0, 6.0),
+                (4.0, 9.0),
+                (0.0, 9.0),
+            ]],
+        );
+        check("step", &step);
+
+        // An outer square with a hole: two crossing pairs on each slab.
+        let holed = region(
+            "holed",
+            vec![
+                vec![(0.0, 0.0), (10.0, 0.0), (10.0, 10.0), (0.0, 10.0)],
+                vec![(3.0, 3.0), (7.0, 3.0), (7.0, 7.0), (3.0, 7.0)],
+            ],
